/// (`mobjinfo_t`)
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MobjInfo {
    /// Editor thing number (THINGS lump `type`), `-1` if not placeable.
    pub doomednum: i32,
    pub spawnstate: StateNum,
    pub spawnhealth: i32,
    pub seestate: StateNum,
    pub seesound: Sfx,
    pub reactiontime: i32,
    pub attacksound: Sfx,
    pub painstate: StateNum,
    pub painchance: i32,
    pub painsound: Sfx,
    pub meleestate: StateNum,
    pub missilestate: StateNum,
    pub deathstate: StateNum,
    pub xdeathstate: StateNum,
    pub deathsound: Sfx,
    pub speed: Fixed,
    pub radius: Fixed,
    pub height: Fixed,
    pub mass: i32,
    pub damage: i32,
    pub activesound: Sfx,
    /// See [`mobj_flag`].
    pub flags: i32,
    pub raisestate: StateNum,
}

